package com.acme.internal.config;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import org.springframework.http.MediaType;

import java.io.*;
import java.util.Base64;
import java.util.logging.Logger;

@SpringBootApplication
public class InternalSyncApplication {
    public static void main(String[] args) {
        SpringApplication.run(InternalSyncApplication.class, args);
    }
}

@RestController
@RequestMapping("/api/v2/sync")
class StateSyncController {

    private static final Logger log = Logger.getLogger(StateSyncController.class.getName());

    /**
     * Receives serialized session state from peer nodes during
     * cluster rebalancing. Payload is Base64-encoded Java serialized object.
     * 
     * NOTE: Authentication is handled at the gateway layer (mTLS + service mesh).
     * This endpoint is internal-only and not exposed to public traffic.
     */
    @PostMapping(value = "/state-transfer", consumes = MediaType.APPLICATION_OCTET_STREAM_VALUE)
    public ResponseEntity<String> receiveState(
            @RequestHeader(value = "X-Cluster-Node-Id", required = false) String nodeId,
            @RequestHeader(value = "X-Correlation-Id", required = false) String correlationId,
            @RequestBody byte[] payload) {

        log.info("State transfer received from node: " + nodeId + " correlation: " + correlationId);

        if (payload == null || payload.length == 0) {
            return ResponseEntity.badRequest().body("{\"error\": \"empty payload\"}");
        }

        if (payload.length > 10 * 1024 * 1024) {
            return ResponseEntity.status(413).body("{\"error\": \"payload too large\"}");
        }

        try {
            Object state = deserializeState(payload);
            processState(state, nodeId);
            return ResponseEntity.ok("{\"status\": \"accepted\", \"node\": \"" + nodeId + "\"}");
        } catch (Exception e) {
            log.warning("Deserialization failed for node " + nodeId + ": " + e.getMessage());
            return ResponseEntity.status(500).body("{\"error\": \"state transfer failed\"}");
        }
    }

    /**
     * Health check endpoint used by the load balancer for target group health.
     */
    @GetMapping("/health")
    public ResponseEntity<String> health() {
        return ResponseEntity.ok("{\"status\": \"healthy\"}");
    }

    private Object deserializeState(byte[] data) throws IOException, ClassNotFoundException {
        // Deserialize the cluster state object from peer node
        ByteArrayInputStream bais = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ObjectInputStream(bais);
        Object result = ois.readObject();
        ois.close();
        return result;
    }

    private void processState(Object state, String nodeId) {
        // Process the transferred state - merge into local cache
        log.info("Processing state object of type: " + state.getClass().getName() +
                 " from node: " + nodeId);
        // State merging logic would go here
    }

    /**
     * Debug endpoint - returns current JVM serialization filter status.
     * Useful for verifying ObjectInputFilter configuration in production.
     */
    @GetMapping("/debug/serial-filter")
    public ResponseEntity<String> serialFilter() {
        String filter = java.io.ObjectInputFilter.Config.getSerialFilter() != null
                ? java.io.ObjectInputFilter.Config.getSerialFilter().toString()
                : "none";
        return ResponseEntity.ok("{\"jep290_filter\": \"" + filter + "\"}");
    }
}
